import {portView,vlanColor} from './port-view.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderPort(canvas,p,n,proxy,i,member,attached,alias){
 const side=i%2?'right-port':'left-port';
 if(member)return `<div data-anchor="${esc(p.id)}" class="port member-slot ${side}" title="Внутренняя привязка: ${esc(p.name)}"><span class="port-dot"></span><span class="port-caption">↳ ${esc(p.name)}</span></div>`;
 const view=portView(n,p),connected=canvas.getState().links.some(l=>l.a===p.id||l.b===p.id),lagError=canvas.lag?.errors.get(p.id),colors=view.vlans.map(vlanColor),bands=colors.map((c,i)=>`${c} ${i/colors.length*100}% ${(i+1)/colors.length*100}%`).join(',');
 const title=`${n.name} / ${view.name} · ${p.ip||'без IP'} · ${view.profile}\n${view.role} ${view.detail}${view.lag?'\n'+view.lag:''}${lagError?'\n'+lagError:''}${attached?'\nЭтот интерфейс принадлежит '+attached.host.name+', показан как порт моста '+attached.bridge.name:''}${proxy?'\nКонтакт свёрнутого объекта':''}`;
 return `<button class="port ${p.kind==='physical'?'physical-port':'virtual-port'} ${side} ${connected?'connected':''} ${canvas.pending===p.id?'pending':''} ${view.role?'structured-port':''} ${lagError?'lag-warning':''}" data-anchor="${esc(p.id)}" data-port="${esc(p.id)}" ${alias?`data-alias="${esc(alias)}"`:''} data-vlans="${view.vlans.join(',')}" style="--vlan-color:${colors[0]||'#536b80'};--vlan-bands:linear-gradient(90deg,${bands||'#536b80,#536b80'})" title="${esc(title)}" aria-label="${esc(title.split('\n')[0])}"><span class="port-dot"></span><span class="port-caption"><span class="port-name">${proxy?esc(n.name)+' / ':''}${esc(view.name)}<i class="interface-kind">${p.kind==='physical'?'▣ ФИЗ':'◌ ВИРТ'}</i>${p.ip?' · '+esc(p.ip):''}${view.role?`<b class="port-role ${view.role.toLowerCase()}">${view.role}</b>`:''}</span>${view.detail?`<small class="port-meta">${esc(view.detail)}</small>`:''}${attached?`<small class="port-meta bridge-port-owner">Порт моста · ${esc(attached.host.name)}</small>`:''}${view.lag?`<small class="lag-badge">${esc(view.lag)} · ${!connected?'DOWN':lagError?lagError.includes('ожидание')?'RESERVE':'BLOCKED':'UP'}</small>`:''}</span></button>`;
}
